//! Flag atlas for the server badges.
//!
//! Generated by `scripts/gen-flags.py` from https://flagcdn.com
//! (public-domain flag images). Do not edit by hand.

pub const FLAG_WIDTH: u32 = 24;
pub const FLAG_HEIGHT: u32 = 18;
pub const CELL_WIDTH: u32 = 26;
pub const CELL_HEIGHT: u32 = 20;
pub const ATLAS_COLUMNS: u32 = 18;
pub const ATLAS_WIDTH: u32 = 468;
pub const ATLAS_HEIGHT: u32 = 280;

pub static ATLAS_RGBA: &[u8] = include_bytes!("../assets/flags.rgba");

